-- 2026-09-08 — Import delle 90 certificazioni della tabella Access (export Query1.xlsx) in imprese_certificazioni.
-- Abbinamento impresa per P.IVA (impresa_id, piva o impresa_cf); le righe senza impresa restano fuori e vengono elencate.
-- La tipologia testuale di Access diventa il codice di imprese_certificazioni_tipi; il testo originale resta in fonte.
begin;
create temp table _cert_acc(access_id int, piva text, certificazione smallint, data_certificato date, data_fine date, data_rinnovo date, ente text, note text, numero text, regolamento text, tipologia_access text);
select m.impresa_id, a.certificazione, a.data_certificato, a.data_fine, a.data_rinnovo, nullif(a.ente,''), nullif(a.note,''), nullif(a.numero,''), nullif(a.regolamento,''), a.access_id,
       'Access certificazioni ID_cert '||a.access_id||' — tipologia: '||a.tipologia_access, 'import 2026-09-08'
  from _cert_acc a
  join lateral (select i.impresa_id from imprese i where (i.impresa_id=a.piva or i.piva=a.piva or i.impresa_cf=a.piva) and coalesce(i.elimina,0)=0 order by (i.impresa_id=a.piva) desc limit 1) m on true
 where not exists (select 1 from imprese_certificazioni c where c.access_id=a.access_id);
select 'importate' k, count(*)::text v from imprese_certificazioni where access_id is not null
union all select 'senza impresa', string_agg(a.access_id||' '||a.piva, ', ') from _cert_acc a where not exists (select 1 from imprese i where (i.impresa_id=a.piva or i.piva=a.piva or i.impresa_cf=a.piva) and coalesce(i.elimina,0)=0);
drop table _cert_acc;
commit;
